import{_ as t,o,c as d,ag as i}from"./chunks/framework.BpFM782D.js";const m=JSON.parse('{"title":"doc-consistency","description":"","frontmatter":{},"headers":[],"relativePath":"skills/doc-consistency.md","filePath":"skills/doc-consistency.md","lastUpdated":null}'),a={name:"skills/doc-consistency.md"};function c(r,e,l,n,s,h){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="doc-consistency" tabindex="-1">doc-consistency <a class="header-anchor" href="#doc-consistency" aria-label="Permalink to &quot;doc-consistency&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>doc-consistency</td></tr><tr><td>說明</td><td>文件一致性守衛。修改 blueprint、architecture、IA 相關文件時自動觸發， 確保關聯文件同步更新、版本正確遞增。 當用戶修改路由、導航、sitemap、架構決策、實作計畫等文件時適用。 防止「改了 A 忘了更新 B」的常見問題。 也適用於「更新文件」「改架構」「改 sitemap」「同步文件」等場景。</td></tr><tr><td></td><td></td></tr><tr><td>來源目錄</td><td><code>skills/doc-consistency/</code></td></tr></tbody></table><hr><h1 id="documentation-consistency-skill" tabindex="-1">Documentation Consistency Skill <a class="header-anchor" href="#documentation-consistency-skill" aria-label="Permalink to &quot;Documentation Consistency Skill&quot;">​</a></h1><p>修改文件或規格時自動觸發，確保所有關聯文件保持一致。</p><h2 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h2><p>當以下目錄的檔案被修改時自動觸發：</p><ul><li><code>blueprint/information-architecture/</code></li><li><code>blueprint/architecture/</code></li><li><code>blueprint/design-system/</code></li><li><code>blueprint/archive/</code></li><li><code>docs/</code></li></ul><p>如果專案沒有 <code>blueprint/</code> 目錄結構，此 skill 不適用。</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><h3 id="rule-1-information-architecture-檔案連動" tabindex="-1">Rule 1: Information Architecture 檔案連動 <a class="header-anchor" href="#rule-1-information-architecture-檔案連動" aria-label="Permalink to &quot;Rule 1: Information Architecture 檔案連動&quot;">​</a></h3><p>修改 IA 目錄下任一檔案時，檢查並同步關聯檔案：</p><table tabindex="0"><thead><tr><th>修改檔案</th><th>必須同步檢查</th></tr></thead><tbody><tr><td><code>routes.md</code></td><td><code>navigation.md</code>, <code>sitemap.md</code></td></tr><tr><td><code>navigation.md</code></td><td><code>routes.md</code>, <code>sitemap.md</code></td></tr><tr><td><code>sitemap.md</code></td><td><code>routes.md</code>, <code>navigation.md</code>, <code>page-inventory.md</code></td></tr><tr><td><code>page-inventory.md</code></td><td><code>sitemap.md</code></td></tr></tbody></table><p><strong>動作</strong>：讀取關聯檔案，確認一致性。如有不一致，主動提醒並修正。</p><p>這些檔案互相引用，改了路由但沒更新導航是最常見的遺漏。 對照表讓你不用靠記憶，改一個就知道要查哪些。</p><h3 id="rule-2-版本化文件遞增" tabindex="-1">Rule 2: 版本化文件遞增 <a class="header-anchor" href="#rule-2-版本化文件遞增" aria-label="Permalink to &quot;Rule 2: 版本化文件遞增&quot;">​</a></h3><p>修改架構決策或實作計畫時，遵循版本遞增流程：</p><ol><li>在 <code>archive/</code> 中建立新版本（<code>tech-decisions-vN+1.md</code> 或 <code>implementation-plan-vN+1.md</code>）</li><li>同步摘要至 <code>architecture/overview.md</code></li><li>更新 <code>README.md</code> 中的版本引用</li><li>更新所有引用舊版本的檔案</li></ol><p><strong>禁止</strong>：</p><ul><li>直接覆蓋現有版本檔案（歷史記錄會消失，無法追溯決策演變）</li><li>只更新 overview 而不建立 archive 版本（違反可追溯性原則）</li></ul><h3 id="rule-3-blueprint-先讀後改" tabindex="-1">Rule 3: Blueprint 先讀後改 <a class="header-anchor" href="#rule-3-blueprint-先讀後改" aria-label="Permalink to &quot;Rule 3: Blueprint 先讀後改&quot;">​</a></h3><p>修改任何 blueprint 相關檔案前：</p><ol><li>先讀取 <code>architecture/overview.md</code> 了解全局</li><li>確認修改不與現有架構決策衝突</li><li>如需變更架構決策，先建立新版本（Rule 2）</li></ol><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><p>完成文件修改後，確認：</p><ul><li>[ ] 關聯的 IA 檔案已同步（Rule 1）</li><li>[ ] 版本化文件已正確遞增（Rule 2）</li><li>[ ] 修改與 architecture/overview.md 一致（Rule 3）</li><li>[ ] 無孤立引用（指向已不存在的檔案或版本）</li></ul><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>銜接</th><th>說明</th></tr></thead><tbody><tr><td>前置</td><td><code>feature-kickoff</code> skill 的 Step 1（讀取 blueprint）</td></tr><tr><td>並行</td><td>與 <code>quality-gate</code> skill 的 Phase 2（security scan）獨立</td></tr><tr><td>後續</td><td><code>git-workflow</code> skill（commit 時標記 <code>docs:</code> 或 <code>chore:</code>）</td></tr></tbody></table>',28)])])}const p=t(a,[["render",c]]);export{m as __pageData,p as default};
